tools/build_training_extras.py from scripts/training_extras/*.lua: edit those, then rebuild. Idempotent; UNDO restores.
Report: notes/training_extras_done.md ]]
local UNDO = false --@UNDO
local SS = game:GetService("ServerStorage")
local log = {}
local function say(...) local t = {} for i = 1, select("#", ...) do t[i] = tostring((select(i, ...))) end table.insert(log, table.concat(t, " ")) end
local ORIG = SS:FindFirstChild("_TX_Originals")
if not ORIG and not UNDO then ORIG = Instance.new("Folder"); ORIG.Name = "_TX_Originals"; ORIG.Parent = SS end
local function ensureOriginal(key, scr)
	local v = ORIG:FindFirstChild(key)
	if not v then v = Instance.new("StringValue"); v.Name = key; v.Value = scr.Source; v.Parent = ORIG end
	return v.Value
end

local NEW = {
	{function() return game.ReplicatedStorage.Modules.Shared.Config end, "TrainingConfig", [[
-- ReplicatedStorage/Modules/Shared/Config/TrainingConfig (ModuleScript, lobby place only)
-- Training extras, step 2 of the Training rebuild (notes/training_extras_done.md). Every extra sits behind a flag here.
-- Play-mode switch without editing code: ReplicatedStorage:SetAttribute("TX_<Name>", false) (or true) before Play / at runtime.
-- Names: AliveDummies, GalleryFill, RoomFXBox, Bullseyes, DpsDummies, JumpPads, Tightropes, SwapBins.
-- A missing or broken config means "all off" (every user pcall-requires it and falls back to the old behaviour).
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local C = {
	AliveDummies = 35,                  -- TrainingManager ENEMIES (was 24); TX_AliveDummies = false -> 24
	GalleryFill = true,                 -- gallery spots (EnemySpots with Gallery = true) refill first
	GalleryRespawn = 1,                 -- seconds before a gallery dummy comes back (arena: TrainingManager RESPAWN_DELAY 2)
	RoomFXBox = true,                   -- RoomFX: Training lights on while the camera is inside this box (arena + gallery)
	RoomBox = { Min = Vector3.new(-140, 588, -140), Max = Vector3.new(364, 660, 140) },
	Bullseyes = { Enabled = true, Radius = 1.5, Respawn = 3, MaxRange = 600 },
	DpsDummies = { Enabled = true, Window = 3, MinSpan = 1, Idle = 2.5, Hold = 2 },
	JumpPads = { Enabled = true, Cooldown = 0.6, Headroom = 4, Apex = 6 },   -- Headroom: root apex this far under CeilingY
	Tightropes = { Enabled = true },
	SwapBins = { Enabled = true, AllowUnowned = true, Reach = 12 },   -- AllowUnowned: Training-only trial of guns you don't own
	CeilingY = 648,                     -- Training ceiling (floor 600 + 48)
}

-- Is this extra on? The TX_<name> attribute on ReplicatedStorage wins over the value above.
function C.On(name: string): boolean
	local a = ReplicatedStorage:GetAttribute("TX_" .. name)
	if a ~= nil then return a == true end
	local v = C[name]
	if type(v) == "table" then return v.Enabled == true end
	return v ~= nil and v ~= false
end

return C
]]},
	{function() return game.ServerScriptService.ServerScripts["[Server] Init"].GameManager.Managers end, "TrainingExtrasManager", [[
-- Managers/TrainingExtrasManager (server, lobby place): Training extras housekeeping (notes/training_extras_done.md).
-- A feature switched off in Shared.Config.TrainingConfig (or by ReplicatedStorage attribute TX_<Feature> = false) has its
-- geometry folder LobbyMap.Training.Extras.<Feature> moved to ServerStorage._TrainingExtrasOff (nothing is deleted), so a
-- disabled feature leaves no parts, prompts or targets behind. Missing config = every extra off.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")
local manager = {}

local FEATURES = { "Bullseyes", "DpsDummies", "JumpPads", "Tightropes", "SwapBins" }

function manager.Start()
	local ok, TX = pcall(require, ReplicatedStorage.Modules.Shared.Config.TrainingConfig)
	local map = workspace:WaitForChild("LobbyMap", 30)
	local t = map and map:WaitForChild("Training", 30)
	local ex = t and t:WaitForChild("Extras", 10)
	if not ex then return end
	for _, name in FEATURES do
		local f = ex:FindFirstChild(name)
		if f and not (ok and TX.On(name)) then
			local off = ServerStorage:FindFirstChild("_TrainingExtrasOff")
			if not off then off = Instance.new("Folder"); off.Name = "_TrainingExtrasOff"; off.Parent = ServerStorage end
			f.Parent = off
		end
	end
end

return manager
]]},
	{function() return game.ServerScriptService.ServerScripts["[Server] Init"].GameManager.Managers end, "ShootableManager", [[
