	{function() return game.ServerScriptService.ServerScripts["[Server] Init"].GameManager.Managers end, "TrainingTargetsManager", [[
-- Managers/TrainingTargetsManager (server, lobby place): floating 1-HP bullseyes in Training (notes/training_extras_done.md).
-- Targets: LobbyMap.Training.Extras.Bullseyes (Ball parts, tag TrainingTarget, built by fix/place_training.lua). Each is
-- CanQuery = true while up, so the shooter's own raycast (WeaponController) stops on it: the first thing a bullet meets wins.
--   * bullseye first -> the client sends no character hit (no dummy damage) and the claimed end point is on the target;
--     CombatManager's server wall check (WeaponUtil.IsPathClear) also refuses a dummy hit through a live target.
--   * dummy first    -> the shot's end point is on the dummy, before any target behind it, so nothing pops.
-- Hit test: ShootableManager.OnShot(origin, endPos, shooter) from CombatManager.afterShot (accepted shots only).
-- A pop hides the target (face off, CanQuery off) for Respawn seconds and tells clients (Events.Training.TargetPop).
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local WeaponUtil = require(ReplicatedStorage.Modules.Shared.WeaponUtil)
local STUDIO = game:GetService("RunService"):IsStudio()
local function why(reason) if STUDIO then workspace:SetAttribute("TX_LastTargetShot", reason) end end   -- Studio-only test trace
local manager = {}

local ok, TX = pcall(require, ReplicatedStorage.Modules.Shared.Config.TrainingConfig)
local live = {}          -- [Part] = true while up
local popEvent

local function pop(target: BasePart, shooter: Player)
	live[target] = nil
	target.CanQuery = false
	target:SetAttribute("Popped", true)
	local face = target:FindFirstChild("Face"); if face then face.Enabled = false end
	popEvent:FireAllClients(target.Position, shooter.UserId)
	task.delay(TX.Bullseyes.Respawn, function()
		if not target.Parent then return end
		target.CanQuery = true
		target:SetAttribute("Popped", nil)
		if face then face.Enabled = true end
		live[target] = true
	end)
end

function manager.OnShot(origin: Vector3, endPos: Vector3, shooter: Player?)
	if not (ok and popEvent and TX.On("Bullseyes")) then return why("off") end
	if not shooter or shooter:GetAttribute("InTraining") ~= true then return why("not in training") end
	if typeof(origin) ~= "Vector3" or typeof(endPos) ~= "Vector3" then return end
	local seg = endPos - origin
	local len = seg.Magnitude
	if len < 0.1 or len > TX.Bullseyes.MaxRange + 5 then return end
	local dir = seg / len
	local R = TX.Bullseyes.Radius
	local best, bestEntry
	for t in live do
		local v = t.Position - origin
		local a = v:Dot(dir)
		if a > 0 then
			local d = (v - dir * a).Magnitude
			if d <= R - 0.02 then   -- the client's own ray (same origin + end point) went through the ball
				-- where the bullet enters the ball: it must be at or before the shot's end point (no hits behind a dummy)
				local entry = a - math.sqrt(math.max(R * R - math.min(d, R) ^ 2, 0))
				if entry <= len + 0.05 and (not bestEntry or entry < bestEntry) then best, bestEntry = t, entry end
			end
		end
	end
	if not best then return why("no target on the shot") end
	-- first thing hit wins: from the muzzle toward the target, the first world part must be that target (walls, other
	-- live targets in front; characters ignored as in WeaponUtil.IsPathClear)
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = WeaponUtil.GetAllCharacters()
	local r = workspace:Raycast(origin, (best.Position - origin) * 1.05, params)
	if r and r.Instance ~= best then return why("blocked by " .. r.Instance.Name) end
	pop(best, shooter)
	why("popped " .. best:GetFullName())
end

function manager.Start()
	if not (ok and TX.On("Bullseyes")) then return end
	local ev = ReplicatedStorage:WaitForChild("Events"):WaitForChild("Training")
	popEvent = ev:FindFirstChild("TargetPop")
	if not popEvent then popEvent = Instance.new("RemoteEvent"); popEvent.Name = "TargetPop"; popEvent.Parent = ev end
	local map = workspace:WaitForChild("LobbyMap", 30)
	local t = map and map:WaitForChild("Training", 30)
	local ex = t and t:WaitForChild("Extras", 10)
	local folder = ex and ex:WaitForChild("Bullseyes", 5)
	if not folder then return end
	for _, p in folder:GetChildren() do
		if p:IsA("BasePart") then
			p.CanQuery = true; p:SetAttribute("Popped", nil)
			local face = p:FindFirstChild("Face"); if face then face.Enabled = true end
			live[p] = true
		end
	end
end

return manager
]]},
	{function() return game.ServerScriptService.ServerScripts["[Server] Init"].GameManager.Managers end, "TrainingDpsManager", [[
-- Managers/TrainingDpsManager (server, lobby place): infinite-HP damage-test dummies with a rolling DPS readout
-- (notes/training_extras_done.md). One dummy per LobbyMap.Training.Extras.DpsDummies.DpsSpot (built by fix/place_training.lua).
-- Not counted in TrainingManager's alive dummies and not on EnemySpots. Hits arrive through the same BindableEvent "OnHit"
-- CombatManager already fires for range dummies (no CombatManager change). Readout: damage of the last `Window` seconds of
-- the current burst up to the last hit / that span (min `MinSpan`), 5 Hz; after `Idle` s without hits it holds greyed for
-- `Hold` s, then resets to 0.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")
local TweenService = game:GetService("TweenService")
local manager = {}

local ok, TX = pcall(require, ReplicatedStorage.Modules.Shared.Config.TrainingConfig)
local BODY = Color3.fromRGB(107, 122, 58)      -- dark olive (Tacticals accent): differs from the red enemies
local LIMB = Color3.fromRGB(40, 44, 36)
local CREAM, SAGE, DIM = Color3.fromRGB(236, 232, 218), Color3.fromRGB(167, 173, 152), Color3.fromRGB(120, 120, 114)
local FONT_H = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Heavy)
local FONT_B = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold)
local ZONE = { Head = Color3.fromRGB(255, 92, 124), Body = Color3.fromRGB(255, 255, 255), Limb = Color3.fromRGB(200, 200, 205), Extremity = Color3.fromRGB(140, 140, 148) }
local HP = 1e6
local dummies = {}

local function label(parent, name, pos, size, color, font)
	local l = Instance.new("TextLabel"); l.Name = name; l.BackgroundTransparency = 1; l.Position = pos; l.Size = size
	l.TextScaled = true; l.TextColor3 = color; l.TextStrokeTransparency = 0.5; l.FontFace = font; l.Text = ""; l.Parent = parent
	return l
end
local function popup(gui, text, color)
	local l = Instance.new("TextLabel"); l.BackgroundTransparency = 1; l.AnchorPoint = Vector2.new(0.5, 1)
	l.Position = UDim2.fromScale(0.5 + (math.random() - 0.5) * 0.4, 0.95); l.Size = UDim2.fromScale(0.5, 0.3); l.Text = text
	l.TextColor3 = color; l.TextStrokeTransparency = 0.4; l.TextScaled = true; l.FontFace = FONT_B; l.Parent = gui
	TweenService:Create(l, TweenInfo.new(1, Enum.EasingStyle.Quad), { Position = l.Position - UDim2.fromScale(0, 0.5), TextTransparency = 1, TextStrokeTransparency = 1 }):Play()
	task.delay(1.1, function() l:Destroy() end)
end
local function fmt(n) local s = tostring(math.floor(n + 0.5)); return (s:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")) end

local function spawnAt(spot: BasePart, parent: Instance)
	local template = ServerStorage:FindFirstChild("RangeAssets") and ServerStorage.RangeAssets:FindFirstChild("Dummy")
	if not template then return end
	local d = template:Clone(); d.Name = "DpsDummy"
	for _, x in d:GetDescendants() do
		if x:IsA("Decal") and x.Parent and x.Parent.Name == "Head" then x:Destroy()
		elseif x:IsA("Shirt") or x:IsA("Pants") or x:IsA("ShirtGraphic") or x:IsA("BodyColors") or x:IsA("Accessory") then x:Destroy()
		elseif x:IsA("BasePart") and x.Name ~= "HumanoidRootPart" then
			x.Color = (x.Name:find("Torso") or x.Name == "Head") and BODY or LIMB; x.Material = Enum.Material.SmoothPlastic
			if x:IsA("MeshPart") then x.TextureID = "" end
		end
	end
	local hum = d:FindFirstChildOfClass("Humanoid")
	hum.MaxHealth = HP; hum.Health = HP; hum.BreakJointsOnDeath = false
	hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
	hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
	local _, size = d:GetBoundingBox()
	d:PivotTo(CFrame.new(spot.Position.X, spot.Position.Y - 3 + size.Y / 2 + 0.05, spot.Position.Z) * spot.CFrame.Rotation)
	for _, p in d:GetDescendants() do if p:IsA("BasePart") then p.Anchored = p.Name == "HumanoidRootPart" end end
	-- readout (BillboardGui Scale = studs: Scale-only UI)
	local gui = Instance.new("BillboardGui"); gui.Name = "DpsReadout"; gui.Size = UDim2.fromScale(7, 3.4)
	gui.StudsOffsetWorldSpace = Vector3.new(0, 3.8, 0); gui.AlwaysOnTop = true; gui.LightInfluence = 0; gui.MaxDistance = 300
	gui.Parent = d:FindFirstChild("Head")
	local plate = Instance.new("Frame"); plate.Name = "Plate"; plate.BackgroundColor3 = Color3.fromRGB(10, 12, 10); plate.BackgroundTransparency = 0.35
	plate.Position = UDim2.fromScale(0.1, 0.36); plate.Size = UDim2.fromScale(0.8, 0.64); plate.Parent = gui
	local uc = Instance.new("UICorner"); uc.CornerRadius = UDim.new(0.18, 0); uc.Parent = plate
	local big = label(plate, "Dps", UDim2.fromScale(0.05, 0.04), UDim2.fromScale(0.9, 0.6), CREAM, FONT_H)
	local small = label(plate, "Detail", UDim2.fromScale(0.05, 0.64), UDim2.fromScale(0.9, 0.3), SAGE, FONT_B)
	local tag = label(gui, "Tag", UDim2.fromScale(0.2, 0.02), UDim2.fromScale(0.6, 0.3), SAGE, FONT_B); tag.Text = "DPS TEST"
	big.Text = "0 DPS"; small.Text = "LAST 0 · TOTAL 0"
	local st = { samples = {}, burstStart = 0, lastHit = -math.huge, last = 0, total = 0, big = big, small = small , gui = gui }
	local onHit = Instance.new("BindableEvent"); onHit.Name = "OnHit"    -- fired by CombatManager on every confirmed hit
	onHit.Event:Connect(function(_, zone, damage)
		local now = os.clock()
		if now - st.lastHit > TX.DpsDummies.Idle then st.samples = {}; st.burstStart = now; st.total = 0 end
		st.lastHit = now; st.last = damage; st.total += damage
		table.insert(st.samples, { t = now, d = damage })
		hum.Health = hum.MaxHealth
		popup(gui, tostring(damage), ZONE[zone] or ZONE.Body)
	end)
	onHit.Parent = d
	hum.HealthChanged:Connect(function(h) if h < HP * 0.5 then hum.Health = HP end end)
	d.Parent = parent
	dummies[d] = st
end

local function tick()
	local now = os.clock()
	local W, MIN, IDLE, HOLD = TX.DpsDummies.Window, TX.DpsDummies.MinSpan, TX.DpsDummies.Idle, TX.DpsDummies.Hold
	for d, st in dummies do
		if not d.Parent then dummies[d] = nil; continue end
		local idle = now - st.lastHit
		local text, detail, colour
		if idle > IDLE + HOLD then
			text, detail, colour = "0 DPS", "LAST 0 · TOTAL 0", DIM
		else
			-- rolling window ending at the last hit: steady while you fire, frozen (greyed) once you stop
			while st.samples[1] and st.samples[1].t < st.lastHit - W do table.remove(st.samples, 1) end
			local span = math.clamp(st.lastHit - st.burstStart, MIN, W)
			local sum = 0
			for _, s in st.samples do if s.t >= st.lastHit - span then sum += s.d end end
			text = fmt(sum / span) .. " DPS"
			detail = "LAST " .. fmt(st.last) .. " · TOTAL " .. fmt(st.total)
			colour = idle > IDLE and DIM or CREAM
		end
		if st.big.Text ~= text then st.big.Text = text end
		if st.small.Text ~= detail then st.small.Text = detail end
		if st.big.TextColor3 ~= colour then st.big.TextColor3 = colour end
	end
end

function manager.Start()
	if not (ok and TX.On("DpsDummies")) then return end
	local map = workspace:WaitForChild("LobbyMap", 30)
	local t = map and map:WaitForChild("Training", 30)
	local ex = t and t:WaitForChild("Extras", 10)
	local folder = ex and ex:WaitForChild("DpsDummies", 5)
	if not folder then return end
	for _, s in folder:GetChildren() do if s:IsA("BasePart") then spawnAt(s, folder) end end
	task.spawn(function() while true do task.wait(0.2); tick() end end)
end

return manager
]]},
	{function() return game.ServerScriptService.ServerScripts["[Server] Init"].GameManager.Managers end, "TrainingBinsManager", [[
-- Managers/TrainingBinsManager (server, lobby place): weapon-swap bins in Training (notes/training_extras_done.md).
-- Remote Events.Training.SwapWeapon(weaponId) (created here). Checks: InTraining, 4/s, standing within Reach of a bin in
-- LobbyMap.Training.Extras.SwapBins, id in WeaponConfig.Loadout. Then CombatManager.SetWeapon (swaps the gun in hand).
-- Owned gun: a normal pick (same as Z: session attribute Loadout). Gun you don't own (AllowUnowned): a TRIAL. The player
-- attribute TrialWeapon is set; the trial ends when the player leaves Training (Loadout goes back to what it was) or picks
-- another bin. NOTHING here writes saved data: no PlayerStore.Set/Grant, no Owned, no saved Loadout (PlayerStore is only read).
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerScriptService = game:GetService("ServerScriptService")
local Players = game:GetService("Players")
local WeaponConfig = require(ReplicatedStorage.Modules.Shared.Config.WeaponConfig)
local manager = {}

local ok, TX = pcall(require, ReplicatedStorage.Modules.Shared.Config.TrainingConfig)
local trials = {}       -- [Player] = { prev = Loadout before the first trial (or false), id = trial gun }
local lastCall = {}

local function owns(player, id)
	local okPS, PlayerStore = pcall(require, ServerScriptService:WaitForChild("Data"):WaitForChild("PlayerStore"))
	if not (okPS and PlayerStore and PlayerStore.Owns) then return false end
	return PlayerStore.Owns(player, id) == true
end
local function ownedList(player)
	local list = {}
	for _, id in WeaponConfig.Loadout do if owns(player, id) then table.insert(list, id) end end
	return table.concat(list, ",")
end
local function nearBin(player)
	local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
	local map = workspace:FindFirstChild("LobbyMap")
	local f = map and map:FindFirstChild("Training") and map.Training:FindFirstChild("Extras") and map.Training.Extras:FindFirstChild("SwapBins")
	if not (root and f) then return false end
	for _, m in f:GetChildren() do
		local pivot = m:IsA("Model") and m:GetPivot()
		if pivot and (pivot.Position - root.Position).Magnitude <= TX.SwapBins.Reach then return true end
	end
	return false
end
local function endTrial(player, restore)
	local tr = trials[player]
	if not tr then return end
	trials[player] = nil
	player:SetAttribute("TrialWeapon", nil)
	if restore then player:SetAttribute("Loadout", tr.prev or nil) end
end

local function onSwap(player, id)
	if not (ok and TX.On("SwapBins")) then return end
	local now = os.clock()
	if lastCall[player] and now - lastCall[player] < 0.25 then return end
	lastCall[player] = now
	if player:GetAttribute("InTraining") ~= true then return end
	if type(id) ~= "string" or not table.find(WeaponConfig.Loadout, id) then return end
	if not nearBin(player) then return end
	local combat = shared.Get and shared.Get("CombatManager")
	if not (combat and combat.SetWeapon) then return end
	local mine = owns(player, id)
	if not mine and not TX.SwapBins.AllowUnowned then return end
	local prev = trials[player] and trials[player].prev or (player:GetAttribute("Loadout") or false)
	if mine then
		endTrial(player, false)                       -- picking another bin ends a trial; an owned pick is a normal pick
		combat.SetWeapon(player, id, true)
	else
		trials[player] = { prev = prev, id = id }    -- set first: the Loadout watcher below sees the trial gun as expected
		player:SetAttribute("TrialWeapon", id)
		combat.SetWeapon(player, id, true)
	end
end

local function watch(player)
	player:SetAttribute("TX_OwnedGuns", nil)
	player:GetAttributeChangedSignal("InTraining"):Connect(function()
		if player:GetAttribute("InTraining") == true then
			player:SetAttribute("TX_OwnedGuns", ownedList(player))   -- the picker marks the others as TRIAL (display only)
		else
			endTrial(player, true)                     -- left Training: the trial gun is gone, Loadout back as it was
		end
	end)
	player:GetAttributeChangedSignal("Loadout"):Connect(function()
		local tr = trials[player]
		if tr and player:GetAttribute("Loadout") ~= tr.id then trials[player] = nil; player:SetAttribute("TrialWeapon", nil) end   -- Z picked an owned gun
	end)
end

function manager.Start()
	if not (ok and TX.On("SwapBins")) then return end
	local ev = ReplicatedStorage:WaitForChild("Events"):WaitForChild("Training")
	local swap = ev:FindFirstChild("SwapWeapon")
	if not swap then swap = Instance.new("RemoteEvent"); swap.Name = "SwapWeapon"; swap.Parent = ev end
	swap.OnServerEvent:Connect(onSwap)
	Players.PlayerAdded:Connect(watch)
	for _, p in Players:GetPlayers() do watch(p) end
	Players.PlayerRemoving:Connect(function(p) trials[p] = nil; lastCall[p] = nil end)
end

return manager
]]},
	{function() return game.StarterPlayer.StarterPlayerScripts.Client.Controllers end, "TrainingPadsController", [[
-- Client/Controllers/TrainingPadsController (client, lobby place): jump pads in Training only (notes/training_extras_done.md).
-- Pads: parts tagged TrainingJumpPad in LobbyMap.Training.Extras.JumpPads, attribute LandAt (world point on the landing
-- surface), Apex (studs above the higher end). The character is client-owned, so the launch is set here: a ballistic arc
-- from the pad to LandAt, its peak kept CeilingY - Headroom below the Training ceiling; the horizontal speed is held each
-- frame (Humanoid air control would bleed it off). While a pad flight lasts, IsPadFlight() is true and WeaponController lets
-- you shoot in the air (the normal no-shooting-mid-hop rule is back as soon as you land). Gated: nothing runs outside Training.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CollectionService = game:GetService("CollectionService")
local TweenService = game:GetService("TweenService")
local Gate = require(ReplicatedStorage:WaitForChild("Modules"):WaitForChild("Shared"):WaitForChild("TrainingGate"))
local RunService = Gate.RunService
local ok, TX = pcall(require, ReplicatedStorage.Modules.Shared.Config.TrainingConfig)

local player = Players.LocalPlayer
local controller = {}
local flight = nil          -- { t0, T, vxz, landedAt }
local lastLaunch = {}       -- [pad] = os.clock()
local params = RaycastParams.new()
params.FilterType = Enum.RaycastFilterType.Include

function controller.IsPadFlight(): boolean
	return flight ~= nil
end

local function flash(pad: BasePart)
	for _, p in pad.Parent:GetChildren() do
		if p.Name == "PadRing" and (p.Position - pad.Position).Magnitude < 3 then
			local c = p.Color
			p.Color = Color3.fromRGB(236, 232, 218)
			TweenService:Create(p, TweenInfo.new(0.45), { Color = c }):Play()
		end
	end
